mapper.select:
SELECT * FROM (
SELECT DATE_FORMAT(pr.completed_at, '%Y-%m-%d') AS date, DATE_FORMAT(pr.completed_at, '%H:%i:%s') AS time, '充值' COLLATE utf8mb4_general_ci AS type, CONCAT( '充值方案: ', COALESCE(rp.description, '自定义充值'), ' (获得 ', pr.coins_received, ' 金币)' ) COLLATE utf8mb4_general_ci AS description, pr.amount_paid AS amount, COALESCE(rp.description, '自定义充值') AS detail_info, -- 充值方案详情 pm.method_name AS payment_method -- 支付方式 FROM payment_record pr LEFT JOIN recharge_plan rp ON pr.plan_id = rp.id LEFT JOIN payment_method pm ON pr.method_id = pm.id WHERE pr.user_id = #{userId} AND pr.payment_status = 'success'
AND pr.`completed_at` >= #{start} AND pr.`completed_at` < DATE_ADD(#{end}, INTERVAL 1 DAY)
UNION ALL
SELECT DATE_FORMAT(gl.`time`, '%Y-%m-%d') AS date, DATE_FORMAT(gl.`time`, '%H:%i:%s') AS time, '消费' COLLATE utf8mb4_general_ci AS type, CONCAT( '打赏房间「', COALESCE(CONVERT(lr.title USING utf8mb4) COLLATE utf8mb4_general_ci, gl.room_id), '」 礼物:', COALESCE(CONVERT(gt.gift_name USING utf8mb4) COLLATE utf8mb4_general_ci, gl.gift_id), ' x', gl.amount ) COLLATE utf8mb4_general_ci AS description, -gl.total_cost AS amount, CONCAT('礼物ID:', gl.gift_id, ' 数量:', gl.amount) AS detail_info, NULL AS payment_method FROM gift_log gl LEFT JOIN gift_type gt ON gl.gift_id = gt.id LEFT JOIN live_room lr ON gl.room_id = lr.room_id WHERE gl.sender_id = #{userId}
AND gl.`time` >= #{start} AND gl.`time` < DATE_ADD(#{end}, INTERVAL 1 DAY)
UNION ALL
SELECT DATE_FORMAT(gl.`time`, '%Y-%m-%d') AS date, DATE_FORMAT(gl.`time`, '%H:%i:%s') AS time, '收入' COLLATE utf8mb4_general_ci AS type, CONCAT( '收到用户「', COALESCE(CONVERT(u.nick_name USING utf8mb4) COLLATE utf8mb4_general_ci, gl.sender_id), '」 的礼物:', COALESCE(CONVERT(gt.gift_name USING utf8mb4) COLLATE utf8mb4_general_ci, gl.gift_id), ' x', gl.amount ) COLLATE utf8mb4_general_ci AS description, gl.total_cost AS amount, CONCAT('来自用户ID:', gl.sender_id, ' 礼物ID:', gl.gift_id) AS detail_info, NULL AS payment_method FROM gift_log gl LEFT JOIN gift_type gt ON gl.gift_id = gt.id LEFT JOIN t_user u ON gl.sender_id = u.user_id WHERE gl.receiver_id = #{userId}
AND gl.`time` >= #{start} AND gl.`time` < DATE_ADD(#{end}, INTERVAL 1 DAY)
) AS t ORDER BY t.date DESC, t.time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM (

SELECT
pr.id
FROM payment_record pr
WHERE pr.user_id = #{userId}
AND pr.payment_status = 'success'

    AND pr.completed_at BETWEEN #{start} AND #{end}


UNION ALL


SELECT
gl.log_id
FROM gift_log gl
WHERE gl.sender_id = #{userId}

    AND gl.`time` BETWEEN #{start} AND #{end}


UNION ALL


SELECT
gl.log_id
FROM gift_log gl
WHERE gl.receiver_id = #{userId}

    AND gl.`time` BETWEEN #{start} AND #{end}

) AS t
